//! The reference user interface as data: every menu, right-click menu, toolbar, toolbox flyout and
//! property bar, item by item and in the reference order (`data.rs`, generated by
//! `cargo run -p xtask -- ui`), plus what Vector does with each item (`bind.rs`).
//!
//! An item's `on` mask says in which selection states it is enabled, one bit per entry of
//! [`CONTEXTS`]; [`context_bit`] gives the current state.

pub mod bind;
#[rustfmt::skip]
pub mod data;

use crate::app::VectorApp;
use vector_core::ObjKind;

/// `Item::sub` for an item that opens nothing.
pub const NO_SUB: u16 = u16::MAX;

/// The selection states of the reference context matrix, in bit order.
#[allow(dead_code)]
pub const CONTEXTS: [&str; 19] = [
    "doc-vazio",
    "retangulo",
    "elipse",
    "curva",
    "texto-artistico",
    "texto-paragrafo",
    "bitmap",
    "grupo",
    "selecao-multipla",
    "tabela",
    "tabela-celulas",
    "simbolo",
    "powerclip",
    "linha-de-cota",
    "conector",
    "varias-paginas",
    "rollover",
    "com-efeitos",
    "sem-documento",
];

/// Item flag: a placeholder hides the items of its source bar that are disabled.
pub const HIDE_DISABLED: u8 = 1;
/// Item flag: a separator goes before the items a placeholder brings in.
pub const ADD_SEPARATOR: u8 = 2;
/// Item flag: the reference shows no state for this item, so `on` is only a guess. Where a
/// placeholder hides disabled items such an item shows only when Vector knows it applies.
pub const UNKNOWN_STATE: u8 = 4;
/// Item flag: the bar leaves the item out until the user adds it back (Quick Customize).
pub const EXCLUDED: u8 = 8;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Kind {
    Button,
    Check,
    Radio,
    /// Opens the bar `sub` as a submenu (or a toolbar's drop-down).
    Flyout,
    /// A button with an attached flyout (`sub`).
    ButtonFlyout,
    /// A toolbox slot: the tools of the flyout `sub`, showing the last one used.
    ToolFlyout,
    Separator,
    /// Stands for a run-time list (recent files, windows, …) or for the items of the bar `sub`.
    Placeholder,
    Combo,
    CellCombo,
    Spin,
    StackedSpin,
    Slider,
    DropDown,
    GroupBegin,
    GroupEnd,
    Anchors,
    Edit,
    Label,
    Spacer,
    Palette,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Face {
    Default,
    TextOnly,
    TextRight,
}

#[derive(Debug)]
pub struct Item {
    /// The reference command id (a GUID), or `vector:…` for Vector's own items.
    pub id: &'static str,
    /// Caption with `&` before the mnemonic letter. Empty for icon-only toolbar items.
    pub text: &'static str,
    pub tip: &'static str,
    pub kind: Kind,
    /// Shortcut keys, the first one shown in menus ("Ctrl+Shift+S").
    pub keys: &'static [&'static str],
    /// Index into [`data::BARS`] of the submenu / flyout / source bar, or [`NO_SUB`].
    pub sub: u16,
    /// Icon name ("" = none).
    pub icon: &'static str,
    /// Whether the menu shows the icon next to the caption.
    pub menu_icon: bool,
    /// Selection states in which the item is enabled, one bit per [`CONTEXTS`] entry.
    pub on: u32,
    pub face: Face,
    pub flags: u8,
}

#[derive(Debug)]
pub struct Bar {
    pub id: &'static str,
    pub name: &'static str,
    pub items: &'static [Item],
}

pub fn bars() -> &'static [Bar] {
    &data::BARS
}

pub fn bar(i: u16) -> Option<&'static Bar> {
    data::BARS.get(i as usize)
}

/// The bar with this id or name.
pub fn bar_named(key: &str) -> Option<(u16, &'static Bar)> {
    data::BARS.iter().enumerate().find(|(_, b)| b.id.eq_ignore_ascii_case(key) || b.name == key).map(|(i, b)| (i as u16, b))
}

/// Caption without the `&` mnemonic marker (`&&` stays a literal `&`).
pub fn plain(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    let mut chars = text.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '&' {
            if chars.peek() == Some(&'&') {
                out.push('&');
                chars.next();
            }
            continue;
        }
        out.push(c);
    }
    out
}

/// The caption an item shows: its text, or the tooltip for icon-only items.
pub fn label(it: &Item) -> &'static str {
    if it.text.is_empty() {
        it.tip
    } else {
        it.text
    }
}

/// The bar index of the main menu bar: with a document open, or the reduced one without.
pub fn menu_bar_index(has_doc: bool) -> u16 {
    let name = if has_doc { "Menu Bar" } else { "Menu Bar (no document)" };
    bar_named(name).map(|(i, _)| i).unwrap_or(0)
}

/// The current selection state as one bit of [`CONTEXTS`].
pub fn context_bit(app: &VectorApp) -> u32 {
    let Some(d) = app.doc() else {
        return 1 << 18;
    };
    let objs: Vec<&vector_core::Object> = d.selection.iter().filter_map(|id| d.doc.find(*id)).collect();
    if objs.is_empty() {
        return if d.doc.pages.len() > 1 { 1 << 15 } else { 1 };
    }
    if objs.len() > 1 {
        return 1 << 8;
    }
    let o = objs[0];
    if !o.effects.is_empty() || matches!(o.kind, ObjKind::Blend(_)) {
        return 1 << 17;
    }
    let bit = match &o.kind {
        ObjKind::Rect(_) => 1,
        ObjKind::Ellipse(_) => 2,
        ObjKind::Path(_) | ObjKind::Polygon(_) | ObjKind::Spiral(_) => 3,
        ObjKind::Text(t) => match t.kind {
            vector_core::text::TextKind::Artistic => 4,
            vector_core::text::TextKind::Paragraph { .. } => 5,
        },
        ObjKind::Image(_) => 6,
        ObjKind::Group(_) => 7,
        // the Table tool on a cell: the cells are the selection
        ObjKind::Table(_) if app.tool == crate::tools::ToolId::Table && app.ts.table_cell.is_some() => 10,
        ObjKind::Table(_) => 9,
        ObjKind::Symbol(_) => 11,
        ObjKind::PowerClip { .. } => 12,
        ObjKind::Dimension(_) => 13,
        ObjKind::Connector(_) => 14,
        ObjKind::Blend(_) => 17,
    };
    1 << bit
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn subs_point_at_bars() {
        for b in bars() {
            for it in b.items {
                if it.sub != NO_SUB {
                    assert!(bar(it.sub).is_some(), "{} / {} points at missing bar {}", b.name, it.id, it.sub);
                }
            }
        }
    }

    #[test]
    fn menu_bars() {
        let doc = bar(menu_bar_index(true)).unwrap();
        let names: Vec<String> = doc.items.iter().map(|i| plain(i.text)).collect();
        assert_eq!(names, ["File", "Edit", "View", "Layout", "Object", "Effects", "Bitmaps", "Text", "Table", "Tools", "Window", "Help"]);
        let nodoc = bar(menu_bar_index(false)).unwrap();
        let names: Vec<String> = nodoc.items.iter().map(|i| plain(i.text)).collect();
        assert_eq!(names, ["File", "Tools", "Window", "Help"]);
    }

    #[test]
    fn plain_strips_mnemonics() {
        assert_eq!(plain("Save &As..."), "Save As...");
        assert_eq!(plain("Black && White"), "Black & White");
    }
}
